//! `Float64Array` en tableaux, comme le cœur les rend), relevée avec `node` sur la même entrée ; la parité complète est celle du
//! banc (`tools/ch064-parite.cjs --module decision`).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::indexing_slicing)]
use crate::essais_j4::{appel, ecrire, lire};
