const LEVIERS: &str = r#"{"exact":true,"autreRail":true,"anomalieMinMm":10,"anomalieMaxMm":45,"sousTauCoherentMm":8,"sousTauCorrige":false,"voisins":true,"transport":true,"voisinsRaffineMm":8,"voisinsEcartMaxMm":10,"vetoVoieMm":45,"raffineObligatoire":true,"anomalieNonCorrigeeRien":true,"consensus":true,"consensusEcartMm":10,"consensusVoieMm":15,"consensusVoieProche":true,"selectionRefMm":null,"consensusTous":false,"voieProcheMaxCuts":5,"diag":false,"vetoVoieAbsMm":100,"voieIncoherenteMm":40,"contreChaineZones":null,"contreChaineVoieMm":null,"contreChaineMm":null,"validerSansVoieMinP":null,"anomalieMinRienMm":null,"anomalieMinRienSansVoieMm":null,"corrigeVoieMaxMm":null,"sansVoieRien":false,"voieListe":false,"voieListeFenetre":8,"deuxiemePasse":0,"passe2Leviers":null,"passesAlternees":false,"branche":true,"brancheMm":8,"brancheVertMm":60,"brancheMaxCuts":6,"brancheExtrapCuts":2,"brancheEcartement":[1380,1520],"voieProcheSureCuts":null,"soutienMinDessus":null,"soutienMinFlanc":null,"rechercheDiag":false,"voieAbsFenetre":6,"rechercheADV":true,"rechZones":["adv","abords"],"rechEcartMm":15,"rechMaxDeplMm":300,"rechVoieMaxMm":80,"rechHauteurMaxMm":25,"rechProcheMaxCuts":6,"rechUniqueMm":15,"rechRemplace":true,"rechRemplaceMm":12,"rechSansPaireRien":false,"rechVoieParCutMm":40,"rechContraMinMm":22,"rechContraMaxMm":45,"rechContraRien":true,"rechMinTop":15,"rechMinFace":6,"rechRatioMax":1.5,"rechDedupMm":5,"rechArret":true,"rechGraineDecalMm":0,"rechDiagLarge":false,"rechOrdreGraines":null,"rechEncadre":true,"rechEncadreMaxCuts":1,"rechEncadreSautMm":15,"rechEncadreEcartMm":15,"corrigeValideZones":["adv"],"anomalieNonCorrigeePMin":0.8,"anomalieNonCorrigeeVoieMm":35,"rechPaireTopMin":60,"rechContraRatioMax":1.5,"rechSauteProcheMm":2.5,"rechSauteProcheCuts":2,"rechSauteProcheZones":null,"voisinsCoherents":true,"voisinsCoherentsParCutMm":40,"voisinsCoherentsBaseMm":15,"rechVoisinsMin":null,"brancheDernier":true,"rechListeResMm":null,"rechListeVoieMm":20,"rechListeZones":null}"#;

fn entree(f: &str, args: &str) -> V {
    let a = appel(f, args);
    crate::js::o(vec![("f", crate::js::s(f)), ("a", V::Tableau(a.a.into_iter().map(Some).collect())), ("leviers", lire(LEVIERS))])
}
fn verifier(f: &str, args: &str, attendu: &str) {
    let r = crate::appeler(crate::GCV2_L1, &entree(f, args)).unwrap_or_else(|e| panic!("{f} : {e:?}"));
    assert_eq!(ecrire(&r), attendu, "{f}");
}

