#[test]
fn gcv2_l1_hors_domaine_sans_panique() {
    // entrées hostiles : jamais de panique ; un refus récupérable (la façade rejoue le JS) ou l'erreur même du JS
    for (f, a) in [("deciderL1", "[null]"), ("deciderDiffere", "[{}]"), ("hypothesesDuCut", "[{}]"), ("casDuDiffere", "[{}]"), ("voieAbsolue", "[null,1,[{\"identity\":{\"cut\":2},\"positions\":{}}]]"),
        ("pairesRecentrees", "[null,[{\"left\":[0,0],\"right\":[0,0]}],1435,null,10]"), ("modeleFige", "[{\"format\":\"x\"}]"), ("coder", "[{\"p\":-1},{}]")] {
        let r = crate::appeler(crate::GCV2_L1, &entree(f, a));
        assert!(matches!(r, Err(ariane_js::Echec::HorsDomaine(_) | ariane_js::Echec::Js { .. })), "{f} : {r:?}");
    }
    // sans leviers (la façade les envoie toujours) : refus
    let e = crate::js::o(vec![("f", crate::js::s("transfo")), ("a", V::Tableau(vec![]))]);
    assert!(crate::appeler(crate::GCV2_L1, &e).is_err());
}
